c-07-array:
#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int somme = 0, max = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        somme += x;
        if (i == 0 || x > max) {
            max = x;
        }
    }
    printf("%d\n%d\n", somme, max);
    return 0;
}

