import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int somme = 0;
        int max = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            somme += x;
            if (x > max) {
                max = x;
            }
        }
        System.out.println(somme);
        System.out.println(max);
    }
}

